  const [lo, hi] = scale(ys), n = pts.length; const x = i => L + i / (n - 1) * (W - L - R), y = v => T + (1 - (v - lo) / (hi - lo)) * (H - T - B);
  const fmt = o.fmt || (v => v.toFixed(0)); const col = o.color || 'var(--ink)'; const d = pts.map((p, i) => (i ? 'L' : 'M') + x(i).toFixed(1) + ' ' + y(p.y).toFixed(1)).join('');
  const base = o.base != null ? y(o.base) : H - B; let g = '';
