  const W = 640, H = 170, L = 8, B = 22, mx = Math.max(1, ...h.map(b => b.n)), bw = (W - L * 2) / h.length, zx = L + (0 - h[0].from) / (h[h.length - 1].to - h[0].from) * (W - L * 2);
