/* ---------- sheets ---------- */
const dlg = () => $('#dlg');
function sheet(html, mount) { dlg().innerHTML = '<div class="sheet">' + html + '</div>'; if (!dlg().open) dlg().showModal(); dlg().scrollTop = 0; if (mount) mount(dlg()); }
const closeSheet = () => { if (dlg().open) dlg().close(); };
document.addEventListener('click', e => { if (e.target === dlg()) closeSheet(); });
function formVals(f) { const o = {}; $$('[name]', f).forEach(el => { if (el.type === 'checkbox') o[el.name] = el.checked; else if (el.type === 'radio') { if (el.checked) o[el.name] = el.value; } else o[el.name] = el.type === 'number' ? (el.value === '' ? null : Number(el.value)) : el.value; }); return o; }
