async function loadState() { S.st = await api('GET', '/state'); badges(); return S.st; }

/* ---------- views ---------- */
const V = {};
const head = (t, sub, right) => '<div class="head"><div><h1>' + t + '</h1>' + (sub ? '<div class="sub">' + sub + '</div>' : '') + '</div>' + (right || '') + '</div>';
const mood = r => ({ RISK_ON: 'risk-on', RISK_OFF: 'risk-off', NEUTRAL: 'neutral' }[r] || 'unknown');
const breakerBanner = b => b && b.tripped ? '<div class="banner"><b>Stand aside.</b> ' + b.reasons.map(esc).join(' ') + '</div>' : '';
const staleMacro = st => { const u = st.macroUpdatedAt; const d = u ? (Date.now() - Date.parse(u)) / 86400000 : null; return (d == null || d > 45) ? '<div class="warnbox" style="margin:-8px 0 24px">The central-bank rates the advisor uses ' + (d == null ? 'have never been confirmed' : 'were last updated ' + Math.round(d) + ' days ago') + '. <a href="#/settings">Check them in Settings</a>.</div>' : ''; };

V.desk = async v => {
  const [st, sigs, open, stats] = await Promise.all([loadState(), api('GET', '/signals?status=new'), api('GET', '/trades?status=OPEN'), api('GET', '/stats')]);
  const s = stats.stats, b = st.breaker;
  let h = head('Desk', st.brief ? 'Last brief ' + ago(st.brief.at) + '. Market mood ' + mood(st.brief.regime) + (st.brief.vix != null ? ', VIX ' + Number(st.brief.vix).toFixed(1) : '') + '.' : 'Waiting for the first brief from the advisor.') + breakerBanner(b) + staleMacro(st) + dayLink(st.day);
  h += '<div class="kpis"><div class="kpi"><span class="big">' + money(b.equity) + '</span><span class="lbl">Equity, ' + money(b.equity - st.account.startEquity, true) + ' since start</span></div>'
    + '<div class="kpi"><span class="big ' + cls(b.weekR) + '">' + rf(b.weekR, 1) + '</span><span class="lbl">This week, today ' + rf(b.dayR, 1) + '</span></div>'
    + '<div class="kpi"><span class="big">' + (s.n ? pc(s.winRate) : '–') + '</span><span class="lbl">Win rate over ' + s.n + ' trade' + (s.n === 1 ? '' : 's') + '</span></div>'
    + '<div class="kpi"><span class="big ' + cls(s.expR) + '">' + (s.n ? rf(s.expR) : '–') + '</span><span class="lbl">Average result per trade</span></div></div>';
  h += '<section class="blk"><h2>Waiting on you <span class="small muted">' + (sigs.length ? sigs.length + ' new signal' + (sigs.length === 1 ? '' : 's') : 'nothing new') + '</span></h2>' + (sigs.length ? sigs.map(sigCard).join('') : '<div class="empty">No new signals. The advisor runs every weekday at 23:15, and most days the right trade is no trade.</div>') + '</section>';
  h += '<section class="blk"><h2>Open trades <span class="small muted">' + open.length + ' open, ' + b.openRiskPct.toFixed(1) + '% of equity at risk</span></h2>' + (open.length ? '<div class="card list">' + open.map(openRow).join('') + '</div>' : '<div class="empty">Nothing open. When you take a signal it appears here, measured against its stop and targets.</div>') + '</section>';
  h += '<section class="blk"><h2>Recent results</h2><div class="card">' + tape(stats.recent) + '</div></section>';
  if (st.brief && st.brief.pairs.length) h += '<section class="blk"><h2>Latest brief <span class="small muted">every pair the advisor checked</span></h2><div class="card list brief">' + st.brief.pairs.map(p => '<div class="li"><span class="pair" style="font-size:16px;width:78px">' + esc(p.pair) + '</span><span class="dir ' + esc(p.direction) + '">' + esc(p.direction) + '</span><span class="grow small muted">' + esc((p.vetoes && p.vetoes[0]) || p.strategy || '') + '</span><span class="pill ' + (p.decision === 'ENTER' ? 'gain' : p.decision === 'WATCH' ? 'warn' : '') + '">' + esc(p.decision) + (p.score != null ? ' ' + p.score : '') + '</span></div>').join('') + '</div></section>';
  v.innerHTML = h; bind(v);
};
const dayLink = d => d && (d.armed || d.open) ? '<a class="card row" href="#/day" style="text-decoration:none;color:inherit;margin:-8px 0 24px"><span style="width:22px">' + ic('day') + '</span><span class="grow"><b>Day trading:</b> ' + [d.armed ? d.armed + ' armed signal' + (d.armed > 1 ? 's' : '') : '', d.open ? d.open + ' open trade' + (d.open > 1 ? 's' : '') : ''].filter(Boolean).join(', ') + '</span><span class="pill blue">' + esc(String(d.state).replace('_', ' ').toLowerCase()) + '</span></a>' : '';
function sigCard(x) {
  const ai = x.ai_verdict === 'REJECT' ? '<span class="pill loss">AI rejected</span>' : x.ai_verdict === 'REDUCE_SIZE' ? '<span class="pill warn">AI: smaller size</span>' : x.ai_verdict === 'APPROVE' ? '<span class="pill gain">AI approved</span>' : x.ai_verdict === 'UNREVIEWED' ? '<span class="pill">AI review failed</span>' : '';
  const entryNote = x.entry_type === 'stop' ? 'Enter on a break of ' + fp(x.pair, x.entry) + ' (stop order, cancel after 2 days)' : 'Enter near ' + fp(x.pair, x.entry);
  return '<article class="card sigcard' + (x.status === 'new' ? ' flag' : '') + '"><div class="top"><div><div class="row wrap"><span class="pair">' + esc(x.pair) + '</span><span class="dir ' + esc(x.direction) + '">' + esc(x.direction) + '</span>' + ai + '</div><div class="small muted">' + esc(x.strategy || '') + ', ' + ago(x.created_at) + (x.regime ? ', market ' + mood(x.regime) : '') + '</div></div><div class="score" title="Advisor score">' + (x.score != null ? x.score : '–') + ' <small>/100</small></div></div>'
    + meter(x.breakdown) + planRuler(x)
    + '<p class="small"><b>' + entryNote + '.</b> Size ' + Math.round(x.units || 0).toLocaleString() + ' units, risking about ' + money(x.risk_usd) + '.</p>'
    + (x.thesis ? '<p class="small">' + esc(x.thesis) + '</p>' : '') + (x.key_risk ? '<p class="small muted">Main risk: ' + esc(x.key_risk) + '</p>' : '') + (x.invalidation ? '<p class="small muted">Wrong if: ' + esc(x.invalidation) + '</p>' : '')
    + (x.status === 'new' ? '<div class="row wrap" style="margin-top:12px"><button class="btn gain" data-take="' + x.id + '">I took this trade</button><button class="btn ghost" data-skip="' + x.id + '">Skip</button></div>' : '<p class="small muted" style="margin:8px 0 0">' + statusLine(x) + '</p>') + '</article>';
}
function statusLine(x) {
  const head = ({ taken: 'You took it.', skipped: 'Skipped' + (x.skip_reason ? ' (' + esc(x.skip_reason.toLowerCase()) + ')' : '') + '.', rejected: 'Rejected by the AI risk officer.' }[x.status] || '');
  const sh = x.shadow_r != null ? ' Followed to the letter it made <b class="' + cls(x.shadow_r) + '">' + rf(x.shadow_r) + '</b> (' + ({ STOP: 'stopped out', TRAIL: 'trailing stop', T2: 'hit final target', TIME: 'time stop', EXPIRED: 'still open after a month' }[x.shadow_reason] || String(x.shadow_reason).toLowerCase()) + ').' : x.shadow_reason === 'NOFILL' ? ' The entry never triggered.' : ' Outcome still playing out.';
  return head + sh;
}
function openRow(t) {
  const dir = t.direction === 'LONG' ? 1 : -1, R = Math.abs(t.entry - t.stop); const trailR = t.trail_stop ? dir * (t.trail_stop - t.entry) / R : null;
  const adv = { TAKE_PARTIAL: 'take partial profit', WARN_NEAR_STOP: 'near the stop', EXIT_STOP: 'stop hit, exit', EXIT_TARGET2: 'final target hit', EXIT_TIME: 'time stop, exit' }[t.advice];
  return '<div class="li click" data-trade="' + t.id + '" style="display:block" tabindex="0" role="button" aria-label="Open ' + esc(t.pair) + ' trade"><div class="row"><span class="pair" style="font-size:18px">' + esc(t.pair) + '</span><span class="dir ' + t.direction + '">' + t.direction + '</span>' + (adv ? '<span class="pill ' + (/exit|stop/.test(adv) ? 'loss' : 'warn') + '">' + adv + '</span>' : '') + '<span class="grow"></span><span class="small muted">' + (t.checked_at ? 'checked ' + ago(t.checked_at) : 'not checked yet') + '</span></div>'
    + ruler({ t1R: t.t1_r, t2R: t.t2_r, nowR: t.last_r != null ? t.last_r : 0, mfeR: t.mfe_r, trailR, p: priceLabels(t) })
    + '<div class="small muted">Stop ' + fp(t.pair, t.curStop || t.stop) + ', entry ' + fp(t.pair, t.entry) + (t.t1 ? ', T1 ' + fp(t.pair, t.t1) : '') + (t.t2 ? ', T2 ' + fp(t.pair, t.t2) : '') + '. Opened ' + dshort(t.opened_at) + ', ' + Math.round(t.units_left).toLocaleString() + ' units' + (t.units_left < t.units ? ' left after a partial' : '') + (t.trail_stop ? ', stop trailed from ' + fp(t.pair, t.stop) : '') + '.</div></div>';
}
function bind(v) {
  $$('[data-take]', v).forEach(b => b.onclick = () => takeSheet(+b.dataset.take));
  $$('[data-skip]', v).forEach(b => b.onclick = () => sheet('<h2>Skip this signal</h2><p class="small muted">Tally keeps following it anyway, so later you can see whether your skips help or hurt.</p><form id="sf"><label class="f">Why are you skipping it?<select name="reason"><option>Not at my screen in time</option><option>I disagree with the setup</option><option>Already enough risk on</option><option>Worried about upcoming news</option><option>Other</option></select></label><div class="actions"><button type="button" class="btn ghost" onclick="closeSheet()">Cancel</button><button class="btn">Skip signal</button></div></form>', d => { $('#sf', d).onsubmit = e => { e.preventDefault(); submit(e.submitter, () => api('POST', '/signals/' + b.dataset.skip + '/skip', formVals(e.target)), () => { closeSheet(); toast('Skipped. Tally will still track how it plays out.'); route(); }); }; }));
  $$('[data-trade]', v).forEach(r => { r.onclick = () => tradeSheet(+r.dataset.trade); r.onkeydown = e => { if (e.key === 'Enter') tradeSheet(+r.dataset.trade); }; });
}
async function takeSheet(id) {
  const x = (await api('GET', '/signals?status=new')).find(s => s.id === id); if (!x) return toast('That signal is no longer open', true);
  const b = S.st && S.st.breaker; const checks = [['stop', 'My stop is placed at the broker'], ['size', 'My size matches the ticket, not bigger'], ['news', 'I checked the calendar for big news in the next day'], ['calm', 'I am not chasing a loss or trading out of boredom']];
  sheet('<h2>Log ' + esc(x.pair) + ' ' + x.direction.toLowerCase() + '</h2>' + (b && b.tripped ? '<div class="banner"><b>Your limits say stand aside.</b> ' + b.reasons.map(esc).join(' ') + '</div>' : '') + '<form id="tf"><div class="grid2"><label class="f">Price you got filled at<input name="fillPrice" type="number" step="any" inputmode="decimal" value="' + fp(x.pair, x.entry) + '" required></label><label class="f">Units<input name="units" type="number" step="1" inputmode="numeric" value="' + Math.round(x.units || 0) + '" required></label></div><label class="f">Stop<input name="stop" type="number" step="any" inputmode="decimal" value="' + fp(x.pair, x.stop) + '" required></label><p class="small" style="margin:4px 0 10px"><b>Before you confirm</b></p>' + checks.map(c => '<label class="check"><input type="checkbox" name="' + c[0] + '"><span>' + c[1] + '</span></label>').join('') + '<label class="f">Note (optional)<textarea name="notes" placeholder="Why you took it and how you feel about it"></textarea></label><div class="actions"><button type="button" class="btn ghost" onclick="closeSheet()">Cancel</button><button class="btn gain">Log trade</button></div></form>', d => {
    $('#tf', d).onsubmit = e => { e.preventDefault(); const f = formVals(e.target); const cl = {}; checks.forEach(c => cl[c[0]] = !!f[c[0]]); if (!Object.values(cl).every(Boolean) && !confirm('Not every box is ticked. Log the trade anyway?')) return; submit(e.submitter, () => api('POST', '/signals/' + id + '/take', { fillPrice: f.fillPrice, units: f.units, stop: f.stop, notes: f.notes, checklist: cl }), () => { closeSheet(); toast('Trade logged. The exit guardian is watching it.'); route(); }); };
  });
}

V.signals = async v => {
  const f = S.sigFilter || 'all'; const rows = await api('GET', '/signals?status=' + f);
  v.innerHTML = head('Signals', 'Every trade the advisor suggested, and what it would have made if followed exactly', '<div class="seg-tabs" role="tablist">' + [['all', 'All'], ['new', 'New'], ['taken', 'Taken'], ['skipped', 'Skipped'], ['rejected', 'AI rejected']].map(k => '<button data-f="' + k[0] + '" class="' + (k[0] === f ? 'on' : '') + '">' + k[1] + '</button>').join('') + '</div>')
    + (rows.length ? rows.map(sigCard).join('<div style="height:12px"></div>') : '<div class="empty">No signals here yet. The advisor posts them after its 23:15 run.</div>');
  $$('[data-f]', v).forEach(b => b.onclick = () => { S.sigFilter = b.dataset.f; route(); }); bind(v);
};

V.trades = async (v, id) => {
  const f = S.trFilter || 'OPEN'; const rows = await api('GET', '/trades' + (f === 'ALL' ? '' : '?status=' + f));
  let h = head('Trades', 'Your journal: every fill, partial and exit', '<div class="row wrap"><div class="seg-tabs">' + [['OPEN', 'Open'], ['CLOSED', 'Closed'], ['ALL', 'All']].map(k => '<button data-f="' + k[0] + '" class="' + (k[0] === f ? 'on' : '') + '">' + k[1] + '</button>').join('') + '</div><button class="btn ghost sm" id="manual">Log a manual trade</button><a class="btn ghost sm" href="/api/export/trades.csv">Export CSV</a></div>');
  if (!rows.length) h += '<div class="empty">No ' + (f === 'ALL' ? '' : f.toLowerCase() + ' ') + 'trades yet.</div>';
  else if (f === 'OPEN') h += '<div class="card list">' + rows.map(openRow).join('') + '</div>';
  else h += '<div class="card tablewrap"><table><thead><tr><th>Pair</th><th>Side</th><th>Closed</th><th>Exit</th><th class="r">Result</th><th class="r">Profit</th></tr></thead><tbody>' + rows.map(t => '<tr class="click" data-trade="' + t.id + '" tabindex="0"><td><b>' + esc(t.pair) + '</b></td><td><span class="dir ' + t.direction + '">' + t.direction + '</span></td><td class="small">' + (t.closed_at ? dshort(t.closed_at) : '<span class="pill blue">open</span>') + '</td><td class="small">' + esc((t.exit_reason || '').toLowerCase()) + '</td><td class="r num ' + cls(t.r) + '">' + (t.status === 'CLOSED' ? rf(t.r) : '–') + '</td><td class="r num ' + cls(t.pnl_usd) + '">' + money(t.pnl_usd, true) + '</td></tr>').join('') + '</tbody></table></div>';
  v.innerHTML = h; $$('[data-f]', v).forEach(b => b.onclick = () => { S.trFilter = b.dataset.f; route(); }); $('#manual', v).onclick = manualSheet; bind(v);
  if (id) tradeSheet(+id);
};
async function tradeSheet(id) {
  let t; try { t = await api('GET', '/trades/' + id); } catch (e) { return toast(e.message, true); }
  const dir = t.direction === 'LONG' ? 1 : -1, R = Math.abs(t.entry - t.stop), open = t.status === 'OPEN';
  const fills = t.fills.map(f => '<tr><td class="small">' + dshort(f.at) + '</td><td>' + ({ entry: 'Entry', partial: 'Partial', exit: 'Exit' }[f.kind] || f.kind) + '</td><td class="num">' + fp(t.pair, f.price) + '</td><td class="r tnum">' + Math.round(f.units).toLocaleString() + '</td><td class="r num ' + cls(f.pnl_usd) + '">' + (f.kind === 'entry' ? '' : money(f.pnl_usd, true)) + '</td></tr>').join('');
  let h = '<div class="row"><h2 class="grow">' + esc(t.pair) + ' <span class="dir ' + t.direction + '">' + t.direction + '</span></h2><button class="btn ghost sm" onclick="closeSheet()">Done</button></div><p class="small muted">' + esc(t.strategy || '') + (t.score ? ', score ' + t.score : '') + (t.regime ? ', market ' + mood(t.regime) : '') + '. Opened ' + dshort(t.opened_at) + (t.closed_at ? ', closed ' + dshort(t.closed_at) : '') + '.</p>';
  h += ruler({ t1R: t.t1_r, t2R: t.t2_r, nowR: open ? (t.last_r != null ? t.last_r : 0) : t.r, mfeR: t.mfe_r, trailR: t.trail_stop ? dir * (t.trail_stop - t.entry) / R : null, p: priceLabels(t) });
  h += '<p class="small muted" style="margin-top:-6px">Stop ' + fp(t.pair, t.stop) + (t.trail_stop ? ' (now ' + fp(t.pair, t.trail_stop) + ')' : '') + ', entry ' + fp(t.pair, t.entry) + (t.t1 ? ', T1 ' + fp(t.pair, t.t1) : '') + (t.t2 ? ', T2 ' + fp(t.pair, t.t2) : '') + '.</p>';
  h += '<div class="grid3" style="margin-bottom:16px;grid-template-columns:repeat(3,minmax(0,1fr))"><div><div class="small muted">' + (open ? 'Banked so far' : 'Result') + '</div><div class="num stat ' + cls(t.r) + '">' + rf(t.r) + '</div><div class="small ' + cls(t.pnl_usd) + '">' + money(t.pnl_usd, true) + '</div></div><div><div class="small muted">Best it got</div><div class="num stat">' + rf(t.mfe_r, 1) + '</div></div><div><div class="small muted">Worst it got</div><div class="num stat">' + rf(t.mae_r, 1) + '</div></div></div>';
  if (open && t.advice) h += '<div class="warnbox" style="margin-bottom:14px">The exit guardian says <b>' + esc({ TAKE_PARTIAL: 'take partial profit', WARN_NEAR_STOP: 'price is near your stop, do not widen it', EXIT_STOP: 'the stop was hit, close the trade', EXIT_TARGET2: 'the final target was hit, close the rest', EXIT_TIME: 'no progress in 15 days, close it' }[t.advice] || t.advice.replace(/_/g, ' ').toLowerCase()) + '</b>' + (t.last_price ? ' (last price ' + fp(t.pair, t.last_price) + ')' : '') + '.</div>';
  if (open) h += '<div class="row wrap" style="margin-bottom:18px"><button class="btn" id="pt">Take partial profit</button><button class="btn loss" id="cl">Close trade</button><button class="btn ghost" id="mv">Move stop</button></div>';
  h += '<h3 style="margin:4px 0 6px">Fills</h3><div class="tablewrap"><table><thead><tr><th>Date</th><th>Kind</th><th>Price</th><th class="r">Units</th><th class="r">Profit</th></tr></thead><tbody>' + fills + '</tbody></table></div>';
  h += '<h3 style="margin:18px 0 6px">Notes</h3><textarea id="tn" aria-label="Notes">' + esc(t.notes || '') + '</textarea><div class="row" style="margin-top:8px"><input id="tg" aria-label="Tags" placeholder="Tags, comma separated" value="' + esc(t.tags || '') + '"><button class="btn ghost sm" id="sv">Save notes</button></div>';
  if (!open && t.followed_plan != null) h += '<p class="small muted" style="margin-top:10px">' + (t.followed_plan ? 'You marked this trade as following the plan.' : 'You marked this trade as breaking the plan.') + '</p>';
  h += '<div style="margin-top:22px"><button class="btn ghost sm" id="del" style="color:var(--loss)">Delete trade</button></div>';
  sheet(h, d => {
    $('#sv', d).onclick = e => submit(e.target, () => api('PATCH', '/trades/' + id, { notes: $('#tn', d).value, tags: $('#tg', d).value }), () => toast('Notes saved'));
    $('#del', d).onclick = () => { if (confirm('Delete this trade and its fills? This cannot be undone.')) api('DELETE', '/trades/' + id).then(() => { closeSheet(); toast('Trade deleted'); route(); }).catch(e => toast(e.message, true)); };
    if (!open) return;
    const lp = t.last_price ? fp(t.pair, t.last_price) : '';
    $('#pt', d).onclick = () => sheet('<h2>Take partial profit</h2><form id="pf"><div class="grid2"><label class="f">Exit price<input name="price" type="number" step="any" inputmode="decimal" value="' + (lp || fp(t.pair, t.t1)) + '" required></label><label class="f">How much to close<select name="fraction"><option value="0.5">Half</option><option value="0.33">A third</option><option value="0.25">A quarter</option></select></label></div><p class="small muted">The plan: half off at T1 (' + fp(t.pair, t.t1) + '), then the stop goes to breakeven.</p><div class="actions"><button type="button" class="btn ghost" onclick="tradeSheet(' + id + ')">Back</button><button class="btn gain">Record partial</button></div></form>', d2 => { $('#pf', d2).onsubmit = e => { e.preventDefault(); const f = formVals(e.target); submit(e.submitter, () => api('POST', '/trades/' + id + '/partial', { price: f.price, fraction: +f.fraction }), () => { toast('Partial recorded'); route(); tradeSheet(id); }); }; });
    $('#cl', d).onclick = () => sheet('<h2>Close ' + esc(t.pair) + '</h2><form id="cf"><label class="f">Exit price<input name="price" type="number" step="any" inputmode="decimal" value="' + lp + '" required></label><label class="f">Why did it close?<select name="reason"><option value="STOP">Stop hit</option><option value="TRAIL">Trailing stop hit</option><option value="T2">Final target hit</option><option value="TIME">Time stop</option><option value="THESIS">The reason for the trade broke</option><option value="MANUAL">Closed by hand</option></select></label><p class="small" style="margin-bottom:8px">Did you follow the plan?</p><div class="row" style="margin-bottom:12px;gap:22px"><label class="check"><input type="radio" name="followed" value="yes" checked><span>Yes</span></label><label class="check"><input type="radio" name="followed" value="no"><span>No</span></label></div><label class="f">One-line lesson<input name="lesson" placeholder="What would you repeat or change?"></label><div class="actions"><button type="button" class="btn ghost" onclick="tradeSheet(' + id + ')">Back</button><button class="btn">Close trade</button></div></form>', d2 => { $('#cf', d2).onsubmit = e => { e.preventDefault(); const f = formVals(e.target); submit(e.submitter, () => api('POST', '/trades/' + id + '/close', { price: f.price, reason: f.reason, followed: f.followed === 'yes', lesson: f.lesson }), () => { closeSheet(); toast('Trade closed'); route(); }); }; });
    $('#mv', d).onclick = () => sheet('<h2>Move stop</h2><form id="mf"><label class="f">New stop<input name="trail_stop" type="number" step="any" inputmode="decimal" value="' + fp(t.pair, t.curStop) + '" required></label><p class="small muted">Only ever tighten a stop. Widening it turns a planned loss into an unplanned one.</p><div class="actions"><button type="button" class="btn ghost" onclick="tradeSheet(' + id + ')">Back</button><button class="btn">Save stop</button></div></form>', d2 => { $('#mf', d2).onsubmit = e => { e.preventDefault(); const ns = formVals(e.target).trail_stop; if (dir * (ns - t.curStop) < 0 && !confirm('That widens your stop. Save it anyway?')) return; submit(e.submitter, () => api('PATCH', '/trades/' + id, { trail_stop: ns }), () => { toast('Stop moved'); route(); tradeSheet(id); }); }; });
  });
}
async function manualSheet() {
  const pairs = (await api('GET', '/settings')).pairs;
  sheet('<h2>Log a manual trade</h2><p class="small muted">For trades you took without a signal. They count in your stats and get watched by the exit guardian.</p><form id="mf"><div class="grid2"><label class="f">Pair<select name="pair">' + pairs.map(p => '<option>' + p + '</option>').join('') + '</select></label><label class="f">Side<select name="direction"><option value="LONG">Long</option><option value="SHORT">Short</option></select></label><label class="f">Entry<input name="entry" type="number" step="any" inputmode="decimal" required></label><label class="f">Stop<input name="stop" type="number" step="any" inputmode="decimal" required></label><label class="f">Target 1<input name="t1" type="number" step="any" inputmode="decimal"></label><label class="f">Target 2<input name="t2" type="number" step="any" inputmode="decimal"></label></div><label class="f">Units<input name="units" type="number" step="1" inputmode="numeric" required></label><label class="f">Note<textarea name="notes"></textarea></label><div class="actions"><button type="button" class="btn ghost" onclick="closeSheet()">Cancel</button><button class="btn">Log trade</button></div></form>', d => { $('#mf', d).onsubmit = e => { e.preventDefault(); submit(e.submitter, () => api('POST', '/trades', formVals(e.target)), () => { closeSheet(); toast('Trade logged'); route(); }); }; });
}

function groupTable(rows, title) {
  if (!rows.length) return '';
  const mx = Math.max(0.01, ...rows.map(r => Math.abs(r.expR)));
  return '<div class="card"><h3 style="margin-bottom:8px">' + title + '</h3><div class="tablewrap"><table><thead><tr><th></th><th class="r">Trades</th><th class="r">Won</th><th>Average</th><th class="r">Total</th></tr></thead><tbody>' + rows.map(r => '<tr><td>' + esc(String(r.key).replace(/^S\d /, '').replace('_', '-')) + '</td><td class="r tnum">' + r.n + '</td><td class="r tnum">' + pc(r.winRate) + '</td><td style="min-width:120px;white-space:nowrap"><span class="bar" style="width:' + Math.max(2, Math.round(Math.abs(r.expR) / mx * 60)) + 'px;background:var(' + (r.expR >= 0 ? '--gain' : '--loss') + ')"></span> <span class="small tnum ' + cls(r.expR) + '">' + rf(r.expR) + '</span></td><td class="r num ' + cls(r.sumR) + '">' + rf(r.sumR, 1) + '</td></tr>').join('') + '</tbody></table></div></div>';
}
const tile = (label, value, note, c) => '<div class="card"><div class="small muted">' + label + '</div><div class="num stat ' + (c || '') + '">' + value + '</div>' + (note ? '<div class="small muted">' + note + '</div>' : '') + '</div>';
V.insights = async v => {
  const days = S.days || 0; const b = await api('GET', '/stats' + (days ? '?days=' + days : '')); const s = b.stats, p = b.profit, sc = b.scorecard;
  let h = head('Insights', 'How the advisor, and you, are actually doing', '<div class="seg-tabs">' + [[30, '30 days'], [90, '90 days'], [365, 'Year'], [0, 'All time']].map(k => '<button data-d="' + k[0] + '" class="' + (k[0] === days ? 'on' : '') + '">' + k[1] + '</button>').join('') + '</div>');
  h += '<div class="kpis"><div class="kpi"><span class="big">' + (s.n ? pc(s.winRate) : '–') + '</span><span class="lbl">Won ' + s.wins + ', lost ' + s.losses + (s.be ? ', ' + s.be + ' flat' : '') + '</span></div><div class="kpi"><span class="big ' + cls(s.expR) + '">' + (s.n ? rf(s.expR) : '–') + '</span><span class="lbl">Expectancy per trade</span></div><div class="kpi"><span class="big">' + (s.n ? (s.pf >= 99 ? 'no losses' : s.pf.toFixed(2)) : '–') + '</span><span class="lbl">Profit factor (won ÷ lost)</span></div><div class="kpi"><span class="big ' + (s.maxDDR ? 'loss' : '') + '">' + (s.maxDDR ? '−' + s.maxDDR.toFixed(1) + 'R' : '–') + '</span><span class="lbl">Deepest drawdown</span></div></div>';
  h += '<section class="blk"><h2>What the numbers say</h2>' + b.insights.map(i => '<p class="tonebar ' + i.tone + '">' + esc(i.text) + '</p>').join('') + '</section>';
  h += '<section class="blk"><h2>Equity</h2><div class="card">' + lineChart(b.curve.map(c => ({ y: c.equity, label: c.date })), { base: b.startEquity, fmt: x => '$' + Math.round(x).toLocaleString(), color: 'var(--gain)', label: 'Equity over time' }) + '</div></section>';
  h += '<section class="blk"><h2>Advisor scorecard <span class="small muted">every signal played out exactly as planned, taken or not' + (sc.pending ? ', ' + sc.pending + ' still playing out' : '') + '</span></h2><div class="grid4">' + [['All signals', sc.all], ['Ones you took', sc.taken], ['Ones you skipped', sc.skipped], ['AI rejected', sc.rejected]].map(x => tile(x[0], x[1].n ? rf(x[1].expR) : '–', x[1].n + ' resolved' + (x[1].n ? ', ' + pc(x[1].winRate) + ' won' : ''), cls(x[1].expR))).join('') + '</div>' + (sc.executionGapR != null ? '<p class="small" style="margin-top:12px">Execution gap on signals you took: <b class="' + cls(sc.executionGapR) + '">' + rf(sc.executionGapR) + '</b> per trade compared with the plan.</p>' : '') + '</section>';
  const rs = Object.entries(p.reasons); h += '<section class="blk"><h2>Profit taking</h2><div class="grid4">' + tile('Reached first target', pc(p.t1Pct)) + tile('Reached final target', pc(p.t2Pct)) + tile('Banked a partial', pc(p.partialPct)) + tile('Winners kept of their best', p.capture == null ? '–' : pc(p.capture)) + '</div>' + (p.n ? '<p class="small muted" style="margin-top:12px;max-width:72ch">On average each trade gave back ' + p.leftR.toFixed(2) + 'R from its best price. Winners lasted ' + p.avgDaysWin.toFixed(1) + ' days and losers ' + p.avgDaysLoss.toFixed(1) + '.' + (rs.length ? ' Exits: ' + rs.map(e => ({ STOP: 'stop', TRAIL: 'trailing stop', T2: 'final target', TIME: 'time stop', THESIS: 'thesis broke', MANUAL: 'by hand' }[e[0]] || e[0].toLowerCase()) + ' ' + e[1]).join(', ') + '.' : '') + '</p>' : '') + '</section>';
  h += '<section class="blk"><h2>How results are spread</h2><div class="card">' + histChart(b.hist) + '</div></section>';
  h += '<section class="blk"><h2>Daily results</h2><div class="card">' + heat(b.daily, (S.st && S.st.account.tzOffset) || 0) + '</div></section>';
  const tbls = [groupTable(b.by.score, 'By advisor score'), groupTable(b.by.strategy, 'By setup'), groupTable(b.by.pair, 'By pair'), groupTable(b.by.regime, 'By market mood'), groupTable(b.by.weekday, 'By entry day'), groupTable(b.by.verdict, 'By AI verdict')].filter(Boolean);
  if (tbls.length) h += '<section class="blk"><h2>Where the edge is</h2><div class="grid2">' + tbls.join('') + '</div></section>';
  if (b.discipline.rated) h += '<section class="blk"><h2>Discipline</h2><div class="card"><p style="margin:0">You followed the plan on <b>' + pc(b.discipline.followedPct) + '</b> of the trades you rated. Following it averaged <b class="' + cls(b.discipline.followedExpR) + '">' + rf(b.discipline.followedExpR) + '</b>' + (b.discipline.brokeN ? '; breaking it averaged <b class="' + cls(b.discipline.brokeExpR) + '">' + rf(b.discipline.brokeExpR) + '</b>' : '') + '.</p></div></section>';
  v.innerHTML = h; $$('[data-d]', v).forEach(x => x.onclick = () => { S.days = +x.dataset.d; route(); });
};

V.lab = async v => {
  const set = await api('GET', '/settings'); const L = S.lab || { pairs: set.pairs.slice(), years: 3, minScore: set.macro.settings.minScore, riskPct: set.account.riskPct, minRR: set.macro.settings.minRR, fundMode: 'static', costPips: 1, maxConcurrent: 4 }; S.lab = L;
  v.innerHTML = head('Lab', 'Replay the advisor\'s rules over past prices before trusting them with money') + '<div class="card"><div class="small muted" style="margin-bottom:6px">Pairs</div><div class="chips">' + set.pairs.map(p => '<span class="chip' + (L.pairs.includes(p) ? ' on' : '') + '" data-p="' + p + '" role="checkbox" aria-checked="' + L.pairs.includes(p) + '" tabindex="0">' + p + '</span>').join('') + '</div>'
    + '<div class="grid4" style="margin-top:16px"><label class="f">Years of history<select id="ly">' + [1, 2, 3, 5, 8].map(y => '<option' + (y === L.years ? ' selected' : '') + '>' + y + '</option>').join('') + '</select></label><label class="f">Minimum score: <b id="lsv" style="color:var(--ink)">' + L.minScore + '</b><input id="ls" type="range" min="40" max="90" step="5" value="' + L.minScore + '"></label><label class="f">Risk per trade %<input id="lr" type="number" step="0.25" min="0.25" max="5" value="' + L.riskPct + '"></label><label class="f">Costs per trade (pips)<input id="lc" type="number" step="0.5" min="0" value="' + L.costPips + '"></label><label class="f">Minimum reward to risk<input id="lm" type="number" step="0.25" min="1" value="' + L.minRR + '"></label><label class="f">Most trades open at once<input id="lx" type="number" step="1" min="1" max="7" value="' + L.maxConcurrent + '"></label><label class="f">Fundamentals<select id="lf"><option value="static"' + (L.fundMode === 'static' ? ' selected' : '') + '>Use today\'s rates</option><option value="off"' + (L.fundMode === 'off' ? ' selected' : '') + '>Technicals only</option></select></label><div style="align-self:end;margin-bottom:12px"><button class="btn" id="run" style="width:100%">Run backtest</button></div></div>'
    + '<div class="warnbox"><b>Know the limits.</b> It uses daily candles and assumes the stop is hit first when a day touches both stop and target. It has no record of past news or past central-bank rates, so "Use today\'s rates" applies today\'s picture to every past day, which flatters the result. Compare it with "Technicals only".</div></div><div id="lout" style="margin-top:28px">' + (S.labOut ? '' : '<div class="empty">Pick your settings and run it. Three years across seven pairs takes a few seconds.</div>') + '</div>';
  $$('.chip', v).forEach(c => { const t = () => { c.classList.toggle('on'); c.setAttribute('aria-checked', c.classList.contains('on')); L.pairs = $$('.chip.on', v).map(x => x.dataset.p); }; c.onclick = t; c.onkeydown = e => { if (e.key === ' ' || e.key === 'Enter') { e.preventDefault(); t(); } }; });
  $('#ls', v).oninput = e => $('#lsv', v).textContent = e.target.value;
  $('#run', v).onclick = e => { if (!L.pairs.length) return toast('Pick at least one pair', true); Object.assign(L, { years: +$('#ly', v).value, minScore: +$('#ls', v).value, riskPct: +$('#lr', v).value, costPips: +$('#lc', v).value, minRR: +$('#lm', v).value, maxConcurrent: +$('#lx', v).value, fundMode: $('#lf', v).value }); $('#lout', v).innerHTML = '<div class="empty"><span class="spin"></span> Downloading prices and replaying every trading day…</div>'; submit(e.target, () => api('POST', '/backtest', L), r => { S.labOut = r; renderLab(); }).then(() => { if (!S.labOut) $('#lout', v).innerHTML = ''; }); };
  if (S.labOut) renderLab();
};
function renderLab() {
  const r = S.labOut, s = r.stats, el = $('#lout'); if (!el) return;
  let h = '<h2 style="margin-bottom:4px">' + r.from + ' to ' + r.to + '</h2><p class="small muted" style="margin-bottom:16px">' + r.opts.pairs.join(', ') + '. Score ' + r.opts.minScore + ' and up, ' + r.opts.riskPct + '% risk, ' + r.opts.costPips + ' pip costs, ' + (r.opts.fundMode === 'off' ? 'technicals only' : 'today\'s rates') + '.</p>';
  h += '<div class="kpis"><div class="kpi"><span class="big ' + cls(r.ret) + '">' + (r.ret >= 0 ? '+' : '−') + Math.abs(r.ret).toFixed(1) + '%</span><span class="lbl">Return, ending at ' + money(r.endEquity) + '</span></div><div class="kpi"><span class="big">' + (s.n ? pc(s.winRate) : '–') + '</span><span class="lbl">Won, over ' + s.n + ' trades</span></div><div class="kpi"><span class="big ' + cls(s.expR) + '">' + rf(s.expR) + '</span><span class="lbl">Per trade, profit factor ' + (s.pf >= 99 ? 'n/a' : s.pf.toFixed(2)) + '</span></div><div class="kpi"><span class="big loss">−' + r.maxDDPct.toFixed(1) + '%</span><span class="lbl">Deepest drawdown, worst run of ' + s.maxLossStreak + ' losses</span></div></div>';
  if (s.n < 30) h += '<p class="tonebar warn">Only ' + s.n + ' trades: too few to judge the strategy. Add years or pairs, or lower the minimum score.</p>';
  h += '<section class="blk"><h2>Equity</h2><div class="card">' + lineChart(r.curve.map(c => ({ y: c.equity, label: c.date })), { base: r.opts.startEquity, fmt: x => '$' + Math.round(x).toLocaleString(), color: 'var(--blue)', label: 'Backtest equity' }) + '</div></section>';
  if (r.mc) h += '<section class="blk"><h2>Luck test <span class="small muted">the same ' + r.mc.steps + ' results reshuffled ' + r.mc.sims + ' times</span></h2><div class="card">' + fanChart(r.mc.bands, r.mc.steps) + '<p class="small" style="margin:12px 0 0;max-width:72ch">The dark band holds the middle half of outcomes, the light band nine in ten. With the same edge in a different order, the typical result is ' + ((r.mc.final.p50 - 1) * 100).toFixed(0) + '% and an unlucky one-in-twenty run ends at ' + ((r.mc.final.p5 - 1) * 100).toFixed(0) + '%. Chance of finishing down: <b>' + pc(r.mc.probLoss) + '</b>. Chance of a 20% drawdown along the way: <b>' + pc(r.mc.probDD20) + '</b>.</p></div></section>';
  h += '<section class="blk"><h2>Where to set the minimum score</h2><div class="card tablewrap"><table><thead><tr><th>Score at least</th><th class="r">Trades</th><th class="r">Won</th><th class="r">Per trade</th><th class="r">Return</th><th class="r">Drawdown</th></tr></thead><tbody>' + r.sens.map(x => '<tr' + (x.thr === r.opts.minScore ? ' style="font-weight:700"' : '') + '><td>' + x.thr + (x.thr === r.opts.minScore ? ' (this run)' : '') + '</td><td class="r tnum">' + x.n + '</td><td class="r tnum">' + (x.n ? pc(x.winRate) : '–') + '</td><td class="r num ' + cls(x.expR) + '">' + (x.n ? rf(x.expR) : '–') + '</td><td class="r num ' + cls(x.ret) + '">' + x.ret.toFixed(1) + '%</td><td class="r num">' + (x.maxDD ? '−' + x.maxDD.toFixed(1) + '%' : '–') + '</td></tr>').join('') + '</tbody></table></div></section>';
  h += '<section class="blk"><h2>How results are spread</h2><div class="card">' + histChart(r.hist) + '</div></section>';
  const tbls = [groupTable(r.byStrategy, 'By setup'), groupTable(r.byPair, 'By pair'), groupTable(r.byRegime, 'By market mood')].filter(Boolean); if (tbls.length) h += '<section class="blk"><div class="grid2">' + tbls.join('') + '</div></section>';
  if (r.trades.length) h += '<section class="blk"><h2>Trades <span class="small muted">latest first' + (r.trades.length > 120 ? ', first 120 shown' : '') + '</span></h2><div class="card tablewrap"><table><thead><tr><th>Pair</th><th>Side</th><th>Setup</th><th>In</th><th>Out</th><th>Exit</th><th class="r">Result</th></tr></thead><tbody>' + r.trades.slice(0, 120).map(t => '<tr><td><b>' + t.pair + '</b></td><td><span class="dir ' + t.direction + '">' + t.direction + '</span></td><td class="small">' + esc(t.strategy.replace(/^S\d /, '')) + '</td><td class="small">' + t.entryDate + '</td><td class="small">' + t.exitDate + '</td><td class="small">' + ({ STOP: 'stop', TRAIL: 'trail', T2: 'target', TIME: 'time', END: 'end of test' }[t.reason] || t.reason) + '</td><td class="r num ' + cls(t.r) + '">' + rf(t.r) + '</td></tr>').join('') + '</tbody></table></div></section>';
  el.innerHTML = h;
}

V.day = (v, sub) => DayDesk.view(v, sub);

V.inbox = async v => {
  const ev = await api('GET', '/events'); const SEV = { alert: 'loss', action: 'warn', info: '' }; const LBL = { brief: 'Brief', signal: 'Signal', trade: 'Trade', day: 'Day trade' };
  v.innerHTML = head('Inbox', 'Messages from the advisor and the exit guardian', ev.some(e => !e.read) ? '<button class="btn ghost sm" id="rd">Mark all read</button>' : '') + (ev.length ? '<div class="card list">' + ev.map(e => '<div class="li' + (e.trade_id || e.signal_id || e.type === 'day' ? ' click' : '') + '" data-t="' + (e.trade_id || '') + '" data-s="' + (e.signal_id || '') + '" data-k="' + esc(e.type) + '" style="align-items:flex-start"><span class="pill ' + SEV[e.severity] + '" style="margin-top:2px;min-width:58px;text-align:center">' + (LBL[e.type] || e.type) + '</span><div class="grow"><div' + (e.read ? '' : ' style="font-weight:700"') + '>' + esc(e.title) + '</div>' + (e.body ? '<div class="small muted notes">' + esc(e.body) + '</div>' : '') + '</div><span class="tiny muted" style="white-space:nowrap">' + ago(e.at) + '</span></div>').join('') + '</div>' : '<div class="empty">Nothing yet. Daily briefs, new signals and trade alerts from n8n land here.</div>');
  const rd = $('#rd', v); if (rd) rd.onclick = () => api('POST', '/events/read').then(() => { loadState(); route(); });
  $$('[data-t]', v).forEach(r => r.onclick = () => { if (r.dataset.k === 'day') location.hash = '#/day'; else if (r.dataset.t) tradeSheet(+r.dataset.t); else if (r.dataset.s) { S.sigFilter = 'all'; location.hash = '#/signals'; } });
  if (ev.some(e => !e.read)) setTimeout(() => api('POST', '/events/read').then(loadState).catch(() => { }), 2500);
};

V.settings = async v => {
  const s = await api('GET', '/settings'); const m = s.macro; const C = Object.keys(m.rates);
  const stanceOpt = (c, val) => '<select data-st="' + c + '" aria-label="' + c + ' direction">' + [[-1, 'Cutting'], [0, 'On hold'], [1, 'Hiking']].map(o => '<option value="' + o[0] + '"' + (+val === o[0] ? ' selected' : '') + '>' + o[1] + '</option>').join('') + '</select>';
  v.innerHTML = head('Settings', 'The advisor reads these on every run, so this is the one place to keep the macro picture current')
    + '<section class="blk"><h2>Central banks <span class="small muted">' + (m.updatedAt ? 'last confirmed ' + ago(m.updatedAt) : 'never confirmed, please check them') + '</span></h2><div class="card tablewrap"><table><thead><tr><th>Currency</th><th>Policy rate %</th><th>Direction</th><th>Next decision</th></tr></thead><tbody>' + C.map(c => { const cb = (m.cb || []).find(x => x.ccy === c); return '<tr><td><b>' + c + '</b></td><td><input type="number" step="0.05" data-rate="' + c + '" aria-label="' + c + ' rate" value="' + m.rates[c] + '" style="max-width:110px"></td><td>' + stanceOpt(c, m.stance[c]) + '</td><td><input type="date" data-cb="' + c + '" aria-label="' + c + ' next decision" value="' + (cb ? cb.date : '') + '" style="max-width:170px"></td></tr>'; }).join('') + '</tbody></table></div><p class="small muted" style="margin-top:8px">The advisor blocks trades in a currency for about 2½ days around its central-bank decision.</p></section>'
    + '<section class="blk"><h2>Advisor rules</h2><div class="card grid3"><label class="f">Minimum score to signal<input id="ms" type="number" value="' + m.settings.minScore + '"></label><label class="f">Minimum reward to risk<input id="mr" type="number" step="0.25" value="' + m.settings.minRR + '"></label><label class="f">Hours to stand aside before big news<input id="eb" type="number" value="' + m.settings.eventBlockHours + '"></label></div></section>'
    + '<section class="blk"><h2>Account</h2><div class="card grid3"><label class="f">Starting equity (USD)<input id="se" type="number" value="' + s.account.startEquity + '"></label><label class="f">Risk per trade %<input id="rp" type="number" step="0.25" value="' + s.account.riskPct + '"></label><label class="f">Your offset from UTC in hours<input id="tz" type="number" value="' + s.account.tzOffset + '"></label></div></section>'
    + '<section class="blk"><h2>Circuit breakers <span class="small muted">Tally tells you to stand aside when any of these trip, and the advisor stops posting new signals</span></h2><div class="card grid4"><label class="f">Daily loss limit (R)<input data-l="maxDailyLossR" type="number" step="0.5" value="' + s.limits.maxDailyLossR + '"></label><label class="f">Weekly loss limit (R)<input data-l="maxWeeklyLossR" type="number" step="0.5" value="' + s.limits.maxWeeklyLossR + '"></label><label class="f">Most open risk (% of equity)<input data-l="maxOpenRiskPct" type="number" step="0.5" value="' + s.limits.maxOpenRiskPct + '"></label><label class="f">Pause after this many losses in a row<input data-l="maxLossStreak" type="number" value="' + s.limits.maxLossStreak + '"></label></div></section>'
    + '<div class="row wrap"><button class="btn" id="save">Save settings</button><button class="btn ghost" id="out">Sign out</button></div>';
  $('#save', v).onclick = e => {
    const nm = JSON.parse(JSON.stringify(m)); C.forEach(c => { nm.rates[c] = +$('[data-rate="' + c + '"]', v).value; nm.stance[c] = +$('[data-st="' + c + '"]', v).value; });
    nm.cb = C.map(c => ({ ccy: c, date: $('[data-cb="' + c + '"]', v).value })).filter(x => x.date); nm.settings = { minScore: +$('#ms', v).value, minRR: +$('#mr', v).value, eventBlockHours: +$('#eb', v).value };
    const lim = {}; $$('[data-l]', v).forEach(i => lim[i.dataset.l] = +i.value);
    submit(e.target, () => api('PUT', '/settings', { macro: nm, account: { startEquity: +$('#se', v).value, riskPct: +$('#rp', v).value, tzOffset: +$('#tz', v).value }, limits: lim }), () => { toast('Saved. The next advisor run uses these.'); S.lab = null; loadState(); });
  };
  $('#out', v).onclick = () => api('POST', '/logout').then(showLogin);
};

/* ---------- router, live updates, boot ---------- */
async function route() {
  const [name, id] = location.hash.replace(/^#\/?/, '').split('/'); const key = V[name] ? name : 'desk';
  $$('[data-r]').forEach(a => a.classList.toggle('on', a.dataset.r === key || (a.dataset.r === 'more' && ['insights', 'lab', 'inbox', 'settings'].includes(key))));
  const v = $('#view'); if (!v) return; if (S.route !== key) { v.innerHTML = '<div class="empty"><span class="spin"></span></div>'; S.route = key; window.scrollTo(0, 0); }
  try { await V[key](v, id); } catch (e) { if (e.message !== 'Signed out') v.innerHTML = '<div class="empty">' + esc(e.message) + '. <button class="btn ghost sm" onclick="route()">Try again</button></div>'; }
}
function live() {
  if (window.es) window.es.close(); const es = window.es = new EventSource('/api/stream');
  es.addEventListener('event', e => { const d = JSON.parse(e.data); if (d.severity !== 'info') toast(d.title); loadState().catch(() => { }); });
  let t; es.addEventListener('refresh', () => { clearTimeout(t); t = setTimeout(() => { if (!dlg().open && S.route !== 'lab' && S.route !== 'settings' && !(S.route === 'day' && DayDesk.isSetup())) route(); else loadState().catch(() => { }); }, 400); });
}
async function boot() {
  try { const th = localStorage.getItem('tally-theme'); if (th) document.documentElement.dataset.theme = th; } catch (e) { }
  const me = await fetch('/api/me').then(r => r.json()).catch(() => ({})); if (!me.authed) return showLogin();
  shell(); S.route = null; await loadState().catch(() => { }); route(); live();
}
window.addEventListener('hashchange', route);
document.addEventListener('visibilitychange', () => { if (!document.hidden && $('#view')) { loadState().catch(() => { }); if (!window.es || window.es.readyState === 2) live(); } });
if ('serviceWorker' in navigator) navigator.serviceWorker.register('/sw.js').catch(() => { });
Object.assign(window, { closeSheet, tradeSheet, toggleTheme, route });
boot();
